/**
 * scripts/verify-staging-capital-factory-chain.js
 * End-to-end verification of:
 * 1. Pure Gold Bullion Capital Contribution (10g @ 995 -> 17.0085g 585 eq into manager pure vault)
 * 2. Factory Handover of Pure Gold (10g @ 995 -> 17.0085g 585 eq to Factory, creating Advance)
 * 3. Factory Receipt absorbing Advance (10g @ 585, 8% markup = 10.8g obligation absorbed by 17.0085g advance -> 0 obligation, 6.2085g remaining advance)
 * 4. Verification that NO profit is generated by capital and factory advance
 * 5. Reversal / Cancellation audit
 */

const { runSqlQuery } = require('./execute-staging-sql');

const STAGING_REF = 'vouehtlmsunebracahon';

async function testCapitalFactoryChain() {
  console.log('==============================================================================');
  console.log('TESTING CAPITAL -> PURE SAFE -> FACTORY HANDOVER -> ADVANCE -> ABSORPTION CHAIN');
  console.log('==============================================================================\n');

  // Find clean director employee on staging
  const empRes = await runSqlQuery(`
    select e.id as employee_id, e.user_id, e.role::text, e.organization_id
    from employees e
    where e.organization_id = '00000000-0000-4001-8001-000000878983'
      and e.role::text in ('director', 'admin')
      and e.user_id is not null
    limit 1;
  `, STAGING_REF);
  const director = empRes[0];
  console.log(`Using Director: id=${director.employee_id}, org=${director.organization_id}`);
  const authHeader = `select set_config('request.jwt.claims', '{"sub": "${director.user_id}", "role": "authenticated"}', false);`;

  // Step 1: Capital Contribution (10g 995 pure bullion)
  console.log('[STEP 1] Recording Pure Bullion Capital (10g @ 995)...');
  const capRes = await runSqlQuery(`
    ${authHeader}
    select public.rpc_record_financial_transaction(
      p_transaction_type := 'capital_contribution',
      p_source_till := 'manager_fine_gold',
      p_amount := 10.0,
      p_currency := 'FINE_GOLD',
      p_category := 'Ta''sischi Toza Oltin Kapitali',
      p_notes := 'Pure gold bullion capital test',
      p_gold_rate := 1150000,
      p_usd_rate := 12850,
      p_idempotency_key := 'idemp_cap_chain_${Date.now()}',
      p_physical_weight := 10.0,
      p_gold_proba := 995,
      p_product_name := 'Toza quyma oltin 995'
    ) as res;
  `, STAGING_REF);
  console.log('Capital contribution result:', JSON.stringify(capRes[0].res));
  const expected585Eq = Math.round((10.0 * 995 / 585) * 10000) / 10000; // 17.0085g

  const vaultAfterCap = (await runSqlQuery(`
    select manager_capital_pure_gold_g, manager_capital_pure_gold_fine_g, manager_refined_gold_grams, current_factory_obligation_g, current_factory_advance_g
    from manager_vault_account where organization_id = '${director.organization_id}';
  `, STAGING_REF))[0];
  console.log('Vault after capital contribution:', vaultAfterCap);
  if (Math.abs(Number(vaultAfterCap.manager_capital_pure_gold_g) - expected585Eq) > 0.001) {
    throw new Error(`FAIL: Manager pure gold safe does not match expected ${expected585Eq}g 585 eq!`);
  }
  if (Number(vaultAfterCap.manager_refined_gold_grams) !== 0) {
    throw new Error('FAIL: Pure gold capital was mistakenly attributed to refining output!');
  }
  console.log('✓ PASS: Pure bullion correctly credited to manager_capital_pure_gold_g without affecting refining output!\n');

  // Step 2: Factory Handover (Handover 10g 995 to Factory)
  console.log('[STEP 2] Handing over 10g 995 Pure Gold from Manager Vault to Factory...');
  const handoverRes = await runSqlQuery(`
    ${authHeader}
    select public.rpc_record_factory_gold_handover(
      p_source_type := 'capital_pure_gold',
      p_physical_weight_g := 10.0,
      p_proba := 995.0,
      p_agreed_equivalent_g := ${expected585Eq},
      p_notes := 'Topshirish: Ta''sischi toza oltini zavodga avans sifatida topshirildi',
      p_idempotency_key := 'idemp_hnd_chain_${Date.now()}'
    ) as res;
  `, STAGING_REF);
  console.log('Factory handover result:', JSON.stringify(handoverRes[0].res));

  const vaultAfterHnd = (await runSqlQuery(`
    select manager_capital_pure_gold_g, current_factory_obligation_g, current_factory_advance_g
    from manager_vault_account where organization_id = '${director.organization_id}';
  `, STAGING_REF))[0];
  console.log('Vault after factory handover:', vaultAfterHnd);
  if (Number(vaultAfterHnd.manager_capital_pure_gold_g) !== 0) {
    throw new Error('FAIL: Pure gold safe was not deducted upon handover!');
  }
  if (Math.abs(Number(vaultAfterHnd.current_factory_advance_g) - expected585Eq) > 0.001) {
    throw new Error(`FAIL: Factory advance ${vaultAfterHnd.current_factory_advance_g} does not match handed over ${expected585Eq}g!`);
  }
  console.log('✓ PASS: Factory advance created correctly! Excess handover is NOT truncated to zero.\n');

  // Step 3: Factory Receipt (10g 585 @ 8% markup = 10.8g obligation)
  console.log('[STEP 3] Recording Factory Receipt of 10g @ 585 with 8% markup (should absorb 10.8g advance)...');
  const rcpRes = await runSqlQuery(`
    ${authHeader}
    select public.rpc_record_factory_receipt(
      p_product_name := 'Uzbek Milliy Uzuk 585',
      p_quantity := 1,
      p_original_physical_g := 10.0,
      p_proba := 585.0,
      p_factory_markup_pct := 8.0,
      p_notes := 'Tovarlar kirimi — avans qoplanishi tekshiruvi',
      p_idempotency_key := 'idemp_rcp_chain_${Date.now()}'
    ) as res;
  `, STAGING_REF);
  console.log('Factory receipt result:', JSON.stringify(rcpRes[0].res));
  const expectedRemAdvance = Math.round((expected585Eq - 10.80) * 10000) / 10000; // 17.0085 - 10.8 = 6.2085g

  const vaultAfterRcp = (await runSqlQuery(`
    select manager_physical_stock_g, current_factory_obligation_g, current_factory_advance_g
    from manager_vault_account where organization_id = '${director.organization_id}';
  `, STAGING_REF))[0];
  console.log('Vault after factory receipt:', vaultAfterRcp);
  if (Number(vaultAfterRcp.current_factory_obligation_g) !== 0) {
    throw new Error(`FAIL: Factory obligation should be 0 (covered by advance), got ${vaultAfterRcp.current_factory_obligation_g}`);
  }
  if (Math.abs(Number(vaultAfterRcp.current_factory_advance_g) - expectedRemAdvance) > 0.001) {
    throw new Error(`FAIL: Remaining advance ${vaultAfterRcp.current_factory_advance_g} does not match expected ${expectedRemAdvance}g!`);
  }
  console.log(`✓ PASS: Factory obligation (10.8g) fully absorbed by advance! Remaining advance = ${vaultAfterRcp.current_factory_advance_g}g\n`);

  // Step 4: Verify Profit Summary (Profit must be 0)
  console.log('[STEP 4] Verifying that capital and factory operations did NOT create artificial profit...');
  const profitRes = await runSqlQuery(`
    ${authHeader}
    select public.rpc_get_accounting_profit_summary() as res;
  `, STAGING_REF);
  console.log('Profit Summary:', JSON.stringify(profitRes[0].res, null, 2));
  const profitData = profitRes[0].res;
  if (profitData.gross_profit_585_g > 0.0001 || profitData.net_profit_585_g > 0.0001) {
    throw new Error(`FAIL: Capital/factory operations generated artificial profit: gross=${profitData.gross_profit_585_g}g, net=${profitData.net_profit_585_g}g`);
  }
  console.log('✓ PASS: Profit is exactly 0.0000g! No fake profit created.\n');

  // Step 5: Clean up test account via Zero-Reset
  console.log('[STEP 5] Cleaning up via Full Test Account Reset (Zero-Reset)...');
  await runSqlQuery(`
    ${authHeader}
    select public.rpc_execute_full_test_reset(
      p_confirmation_code := 'RESET_TEST_ACCOUNT_2026',
      p_reason := 'Clean up after Capital-Factory Chain Test'
    );
  `, STAGING_REF);
  console.log('✓ PASS: Account reset to zero.\n');

  console.log('==============================================================================');
  console.log('ALL CAPITAL -> FACTORY ADVANCE -> ABSORPTION TESTS COMPLETED WITH 100% SUCCESS!');
  console.log('==============================================================================');
}

testCapitalFactoryChain().catch(err => {
  console.error('\n❌ CAPITAL FACTORY CHAIN ERROR:', err);
  process.exit(1);
});
